/**
 * The BBAN structure of every country in the IBAN registry, in the registry's notation: a length
 * followed by `!n` (digits), `!a` (upper case letters) or `!c` (letters and digits).
 *
 * Generated from python-stdnum's `stdnum/iban.dat`
 * (https://github.com/arthurdejong/python-stdnum/blob/master/stdnum/iban.dat), which is itself
 * generated from the SWIFT IBAN Registry, release 101. Do not edit a structure by hand.
 */
export const IBAN_REGISTRY_RELEASE = 101

export interface IbanCountry {
  /** ISO 3166-1 alpha-2 code, the first two characters of the IBAN. */
  code: string
  name: string
  bban: string
}

